def choose_move(observation):
    resources = observation.get('resources', [])
    enemies = observation.get('enemies', [])
    allies = observation.get('allies', [])
    territory = observation.get('territory', {})
    position = observation.get('position', (0, 0))
    grid_size = observation.get('grid_size', (10, 10))
    game_type = observation.get('game_type', '')

    x, y = position

    def clamp(val, min_val, max_val):
        return max(min_val, min(val, max_val))

    def closest_point(points, current):
        return min(points, key=lambda p: abs(p[0]-current[0]) + abs(p[1]-current[1])) if points else None

    dx, dy = 0, 0

    if game_type == 'resource_collection':
        if resources:
            target = closest_point(resources, (x, y))
            dx = target[0] - x
            dy = target[1] - y
        else:
            dx, dy = 0, 0

    elif game_type == 'pursuit_evasion':
        if enemies:
            target = closest_point(enemies, (x, y))
            dx = target[0] - x
            dy = target[1] - y
        else:
            dx, dy = 0, 0

    elif game_type == 'territory_control':
        unclaimed = [pos for pos, owner in territory.items() if owner == 0]
        if unclaimed:
            target = closest_point(unclaimed, (x, y))
            dx = target[0] - x
            dy = target[1] - y
        else:
            dx, dy = 0, 0

    # Constrain to -1, 0, 1
    dx = max(-1, min(1, (dx > 0) - (dx < 0)))
    dy = max(-1, min(1, (dy > 0) - (dy < 0)))
    return [dx, dy]

